// bots + remote players
for (const b of g.bots) {
  if (!b.alive) continue;
  const [mx, my] = toMap(b.pos[0], b.pos[2]);
  ctx.fillStyle = '#ff4040';
  ctx.beginPath();
  ctx.arc(mx, my, 3, 0, Math.PI * 2);
  ctx.fill();
}
for (const r of g.remoteTargets) {
  const [mx, my] = toMap(r.x, r.z);
  ctx.fillStyle = '#ffb040';
  ctx.beginPath();
  ctx.arc(mx, my, 3, 0, Math.PI * 2);
  ctx.fill();
}
